#!/usr/bin/env node
/**
 * check-migration-codegen-alignment.mjs
 *
 * Zero-dependency deterministic Migration <-> CodeGen Alignment Checker for MemberJunction
 * and OpenApp repositories. Verifies 5 invariants in <200ms:
 *
 *   1. 4-Part File Anatomy & Separation:
 *      - Hand DDL strictly above `-- GENERATED BY MemberJunction CodeGen`
 *      - No CodeGen-owned spCreate/spUpdate/spDelete/vw/trgUpdate above banner (unless `-- codegen-override-ok`)
 *      - At least `--min-blank-lines` (default 50) consecutive blank lines before the CodeGen banner header
 *   2. Mandatory CodeGen Section Presence:
 *      - Entity-affecting DDL (CREATE TABLE, ALTER TABLE ADD/ALTER COLUMN/DROP/value-list CHECK) requires a
 *        non-empty CodeGen section (exempt: index-only, sp_updateextendedproperty-only, Metadata_Sync,
 *        Baseline, R__ repeatable, or `-- codegen-not-required:<reason>`)
 *   3. 1:1 DDL <-> CodeGen Coverage Match:
 *      - CREATE TABLE -> Entity INSERT + EntityField INSERTs (apply-time COALESCE(MAX([Sequence]),0)) +
 *        base view + spCreate/spUpdate/spDelete (unless `-- virtual-entity`) + trgUpdate + GRANTs
 *      - ALTER TABLE ADD -> EntityField INSERT/UPDATE (apply-time Sequence) + regenerated view +
 *        regenerated spCreate & spUpdate referencing @Col
 *      - Value-list CHECK constraints -> EntityFieldValue sync statements (unless `-- non-valuelist-check`)
 *   4. Cross-File PR Lockstep (SQL + PG + Generated TS):
 *      - Matching `migrations-pg/*.pg.sql` counterpart exists and references all new/altered tables & columns
 *        (when repo uses `migrations-pg/`, disable with `--no-pg`)
 *      - PR diff includes generated entity TypeScript (`packages/*Entities*\/src/generated/` or
 *        `packages/MJCoreEntities/src/generated/`) referencing new tables/columns (disable with `--no-ts`)
 *   5. PUBLISH_NO_BREAK_POLICY.md Additive Schema Guard:
 *      - Rejects DROP TABLE, DROP COLUMN, sp_rename, and ALTER TABLE ADD ... NOT NULL without DEFAULT
 *        on existing tables (disable on major era bumps with `--allow-breaking`)
 *
 * Usage:
 *   node check-migration-codegen-alignment.mjs [options] [<base> <head>]
 *
 * Options:
 *   --base <ref>               Base git ref (default: $BASE_REF or origin/next)
 *   --head <ref>               Head git ref (omit to check working tree + untracked)
 *   --files <f1,f2,...>        Explicit comma-separated repo-relative file list (skips git diff)
 *   --mode <Enforce|Warn|Off>  Enforcement mode (default: Enforce, or $MIGRATION_ALIGNMENT_MODE)
 *   --min-blank-lines <N>      Minimum consecutive blank lines before CodeGen banner (default: 50)
 *   --allow-breaking           Disable PUBLISH_NO_BREAK_POLICY.md additive schema guard
 *   --no-pg                    Disable PostgreSQL counterpart alignment check
 *   --no-ts                    Disable generated TypeScript entity lockstep check
 *   --json                     Output machine-readable JSON result
 *   --self-test                Run built-in self-test suite across all 5 invariants
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, realpathSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const RED = '\x1b[0;31m';
const YELLOW = '\x1b[0;33m';
const GREEN = '\x1b[0;32m';
const DIM = '\x1b[2m';
const NC = '\x1b[0m';
const GIT_MAX_BUFFER = Number(process.env.MJ_GIT_MAX_BUFFER) || 256 * 1024 * 1024;

const TSQL_MIGRATION_PATH_RE = /(?:^|\/)migrations\/(?:.+\/)?[^/]+\.sql$/i;
const PG_MIGRATION_PATH_RE = /(?:^|\/)migrations-pg\/(?:.+\/)?[^/]+\.pg\.sql$/i;
const FIXTURE_DIR_RE = /(?:^|\/)tests?\//i;
const GENERATED_TS_ENTITY_PATH_RE =
    /(?:^|\/)packages\/(?:[^/]*Entities[^/]*|MJCoreEntities)\/src\/generated\/.+\.ts$/i;

const CODEGEN_BANNER_LINE_RE = /^\s*--\s*GENERATED\s+BY\s+MemberJunction\s+CodeGen\b/i;
const COMMENT_SEPARATOR_LINE_RE = /^\s*--\s*[=\-*]{10,}\s*$/;
const CODEGEN_NOT_REQUIRED_RE = /--\s*codegen-not-required\s*:\s*([^\r\n]+)/i;
const CODEGEN_OVERRIDE_OK_RE = /--\s*codegen-override-ok\b/i;
const VIRTUAL_ENTITY_RE = /--\s*virtual-entity\b/i;
const NON_VALUELIST_CHECK_RE = /--\s*non-valuelist-check\b/i;
const PG_NOT_REQUIRED_RE = /--\s*pg-not-required\b/i;

const MJ_SYSTEM_COLUMNS = new Set(['__mj_createdat', '__mj_updatedat', '__mj_deletedat']);
const SQL_OBJ_PART = String.raw`(?:\$\{[^}]+\}|\[[^\]]+(?:\]\][^\]]*)*\]|"[^"]+"|` + '`' + String.raw`[^` + '`' + String.raw`]+` + '`' + String.raw`|[A-Za-z_#@][A-Za-z0-9_@#$]*)`;
const SQL_QUALIFIED_NAME_SRC = `${SQL_OBJ_PART}(?:\\s*\\.\\s*${SQL_OBJ_PART})*`;

function normalizePath(rawPath) {
    return String(rawPath).replace(/\\/g, '/').replace(/^\.\//, '');
}

function unquoteIdentifier(raw) {
    const trimmed = raw.trim();
    if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
        return trimmed.slice(1, -1).replace(/\]\]/g, ']');
    }
    if (trimmed.startsWith('"') && trimmed.endsWith('"')) {
        return trimmed.slice(1, -1).replace(/""/g, '"');
    }
    if (trimmed.startsWith('`') && trimmed.endsWith('`')) {
        return trimmed.slice(1, -1);
    }
    return trimmed;
}

function parseQualifiedObjectName(raw) {
    const trimmed = raw.trim();
    const parts = [];
    let current = '';
    let inBracket = false;
    let inQuote = false;
    let inBrace = false;

    for (let i = 0; i < trimmed.length; i += 1) {
        const ch = trimmed[i];
        if (ch === '[' && !inQuote) {
            inBracket = true;
            current += ch;
        } else if (ch === ']' && inBracket) {
            if (trimmed[i + 1] === ']') {
                current += ']]';
                i += 1;
            } else {
                inBracket = false;
                current += ch;
            }
        } else if (ch === '"' && !inBracket) {
            inQuote = !inQuote;
            current += ch;
        } else if (ch === '{' && trimmed[i - 1] === '$') {
            inBrace = true;
            current += ch;
        } else if (ch === '}' && inBrace) {
            inBrace = false;
            current += ch;
        } else if (ch === '.' && !inBracket && !inQuote && !inBrace) {
            parts.push(current.trim());
            current = '';
        } else {
            current += ch;
        }
    }
    if (current.trim().length > 0) parts.push(current.trim());
    if (parts.length === 0) return { schemaName: null, objectName: '' };
    if (parts.length === 1) return { schemaName: null, objectName: unquoteIdentifier(parts[0]) };
    return {
        schemaName: unquoteIdentifier(parts[parts.length - 2]),
        objectName: unquoteIdentifier(parts[parts.length - 1]),
    };
}

function isTempTableName(name) {
    return name.startsWith('#') || name.startsWith('@');
}

function isMjSystemColumn(colName) {
    return MJ_SYSTEM_COLUMNS.has(colName.trim().toLowerCase());
}

/**
 * Offset-preserving SQL comment and string-literal masker.
 */
export function stripSqlCommentsAndLiterals(source) {
    const chunks = [];
    let i = 0;
    const n = source.length;
    const stateOpeners = /[-/'["]/g;
    const maskSpan = (start, end) => {
        const nl = source.indexOf('\n', start);
        if (nl === -1 || nl >= end) return ' '.repeat(end - start);
        return source.slice(start, end).replace(/[^\n]/g, ' ');
    };

    while (i < n) {
        stateOpeners.lastIndex = i;
        const opener = stateOpeners.exec(source);
        if (opener === null) {
            chunks.push(source.slice(i));
            break;
        }
        if (opener.index > i) chunks.push(source.slice(i, opener.index));
        i = opener.index;

        const two = source.slice(i, i + 2);
        if (two === '--') {
            const end = source.indexOf('\n', i);
            const stop = end === -1 ? n : end;
            chunks.push(maskSpan(i, stop));
            i = stop;
            continue;
        }
        if (two === '/*') {
            let depth = 1;
            let j = i + 2;
            while (j < n && depth > 0) {
                const open = source.indexOf('/*', j);
                const close = source.indexOf('*/', j);
                if (close === -1) {
                    j = n;
                    break;
                }
                if (open !== -1 && open < close) {
                    depth += 1;
                    j = open + 2;
                } else {
                    depth -= 1;
                    j = close + 2;
                }
            }
            chunks.push(maskSpan(i, j));
            i = j;
            continue;
        }
        if (source[i] === "'") {
            let j = i + 1;
            for (;;) {
                const quote = source.indexOf("'", j);
                if (quote === -1) {
                    j = n;
                    break;
                }
                if (source[quote + 1] === "'") {
                    j = quote + 2;
                    continue;
                }
                j = quote + 1;
                break;
            }
            chunks.push(maskSpan(i, j));
            i = j;
            continue;
        }
        if (source[i] === '[') {
            let j = i + 1;
            for (;;) {
                const bracket = source.indexOf(']', j);
                if (bracket === -1) {
                    j = n;
                    break;
                }
                if (source[bracket + 1] === ']') {
                    j = bracket + 2;
                    continue;
                }
                j = bracket + 1;
                break;
            }
            chunks.push(source.slice(i, j));
            i = j;
            continue;
        }
        if (source[i] === '"') {
            let j = i + 1;
            for (;;) {
                const dq = source.indexOf('"', j);
                if (dq === -1) {
                    j = n;
                    break;
                }
                if (source[dq + 1] === '"') {
                    j = dq + 2;
                    continue;
                }
                j = dq + 1;
                break;
            }
            chunks.push(source.slice(i, j));
            i = j;
            continue;
        }
        chunks.push(source[i]);
        i += 1;
    }
    return chunks.join('');
}

function buildNewlineIndex(text) {
    const offsets = [];
    for (let i = text.indexOf('\n'); i !== -1; i = text.indexOf('\n', i + 1)) offsets.push(i);
    return offsets;
}

function lineNumberAtOffset(newlines, offset) {
    let lo = 0;
    let hi = newlines.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (newlines[mid] < offset) lo = mid + 1;
        else hi = mid;
    }
    return lo + 1;
}

function parseBalancedParenList(text, openIndex) {
    if (text[openIndex] !== '(') return null;
    const items = [];
    const starts = [];
    const ends = [];
    const pushItem = (from, to) => {
        const raw = text.slice(from, to);
        const lead = raw.search(/\S/);
        items.push(raw.trim());
        starts.push(lead === -1 ? to : from + lead);
        ends.push(to);
    };
    let depth = 0;
    let i = openIndex;
    let start = openIndex + 1;
    while (i < text.length) {
        const ch = text[i];
        if (ch === '[') {
            let j = i + 1;
            for (;;) {
                const close = text.indexOf(']', j);
                if (close === -1) { j = text.length; break; }
                if (text[close + 1] === ']') { j = close + 2; continue; }
                j = close + 1; break;
            }
            i = j;
            continue;
        }
        if (ch === '(') { depth += 1; i += 1; continue; }
        if (ch === ')') {
            depth -= 1;
            if (depth === 0) {
                pushItem(start, i);
                return { items, starts, ends, end: i + 1 };
            }
            i += 1;
            continue;
        }
        if (ch === ',' && depth === 1) {
            pushItem(start, i);
            start = i + 1;
            i += 1;
            continue;
        }
        i += 1;
    }
    return null;
}

function findMatchingCloseParen(text, openIndex) {
    if (text[openIndex] !== '(') return -1;
    let depth = 0;
    let i = openIndex;
    while (i < text.length) {
        const ch = text[i];
        if (ch === '[') {
            let j = i + 1;
            for (;;) {
                const close = text.indexOf(']', j);
                if (close === -1) return -1;
                if (text[close + 1] === ']') { j = close + 2; continue; }
                j = close + 1; break;
            }
            i = j;
            continue;
        }
        if (ch === '(') depth += 1;
        else if (ch === ')') {
            depth -= 1;
            if (depth === 0) return i;
        }
        i += 1;
    }
    return -1;
}

function splitTopLevelCommas(text) {
    const results = [];
    let depth = 0;
    let start = 0;
    let i = 0;
    while (i < text.length) {
        const ch = text[i];
        if (ch === '[') {
            let j = i + 1;
            for (;;) {
                const close = text.indexOf(']', j);
                if (close === -1) { j = text.length; break; }
                if (text[close + 1] === ']') { j = close + 2; continue; }
                j = close + 1; break;
            }
            i = j;
            continue;
        }
        if (ch === '(') depth += 1;
        else if (ch === ')' && depth > 0) depth -= 1;
        else if (ch === ',' && depth === 0) {
            results.push({ segment: text.slice(start, i), startOffset: start, endOffset: i });
            start = i + 1;
        }
        i += 1;
    }
    if (start <= text.length) {
        results.push({ segment: text.slice(start), startOffset: start, endOffset: text.length });
    }
    return results;
}

function skipWhitespace(text, pos) {
    let i = pos;
    while (i < text.length && /\s/.test(text[i])) i += 1;
    return i;
}

function splitBatchesWithOffsets(maskedSql) {
    const batches = [];
    const goRe = /^[ \t]*GO[ \t]*(?:\d+[ \t]*)?$/gim;
    let lastEnd = 0;
    let match;
    while ((match = goRe.exec(maskedSql)) !== null) {
        batches.push({ text: maskedSql.slice(lastEnd, match.index), startOffset: lastEnd, endOffset: match.index });
        lastEnd = match.index + match[0].length;
    }
    if (lastEnd <= maskedSql.length) {
        batches.push({ text: maskedSql.slice(lastEnd), startOffset: lastEnd, endOffset: maskedSql.length });
    }
    return batches;
}

function findStatementEndInBatch(batchText, fromOffset) {
    let depth = 0;
    let i = fromOffset;
    while (i < batchText.length) {
        const ch = batchText[i];
        if (ch === '[') {
            let j = i + 1;
            for (;;) {
                const close = batchText.indexOf(']', j);
                if (close === -1) return batchText.length;
                if (batchText[close + 1] === ']') { j = close + 2; continue; }
                j = close + 1; break;
            }
            i = j;
            continue;
        }
        if (ch === '(') depth += 1;
        else if (ch === ')' && depth > 0) depth -= 1;
        else if (ch === ';' && depth === 0) return i;
        i += 1;
    }
    return batchText.length;
}

function detectValueListCheckInRawSlice(rawSlice) {
    const checkRe = /\bCHECK\s*\(/gi;
    let m;
    while ((m = checkRe.exec(rawSlice)) !== null) {
        const openIdx = m.index + m[0].length - 1;
        const closeIdx = findMatchingCloseParen(rawSlice, openIdx);
        const body = closeIdx !== -1 ? rawSlice.slice(openIdx + 1, closeIdx) : rawSlice.slice(openIdx + 1);
        if (/\bIN\s*\(\s*N?'/i.test(body)) return true;
    }
    return false;
}

function hasAnnotationNearLine(rawLines, lineNumber1Based, regex) {
    const startIdx = Math.max(0, lineNumber1Based - 3);
    const endIdx = Math.min(rawLines.length - 1, lineNumber1Based);
    for (let idx = startIdx; idx <= endIdx; idx += 1) {
        if (regex.test(rawLines[idx])) return true;
    }
    return false;
}

function extractFirstIdentifier(segment) {
    const m = new RegExp(`^(${SQL_OBJ_PART})`).exec(segment.trim());
    return m ? unquoteIdentifier(m[1]) : null;
}

function escapeRegExp(literal) {
    return literal.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function matchesViewNameForTable(viewName, tableName) {
    const v = viewName.toLowerCase();
    const t = tableName.toLowerCase();
    if (!v.startsWith('vw')) return false;
    const suffix = v.slice(2);
    if (suffix === t || suffix === `${t}s` || suffix === `${t}es`) return true;
    if (t.endsWith('y') && suffix === `${t.slice(0, -1)}ies`) return true;
    if (suffix.endsWith(t) || suffix.endsWith(`${t}s`) || suffix.endsWith(`${t}es`)) return true;
    if (t.endsWith('y') && suffix.endsWith(`${t.slice(0, -1)}ies`)) return true;
    return false;
}

function isExemptMigrationFileName(filePath) {
    const fileName = normalizePath(filePath).split('/').pop() ?? '';
    if (/Metadata_Sync/i.test(fileName)) return 'Metadata_Sync migration';
    if (/^B\d+__.*Baseline/i.test(fileName)) return 'Baseline migration';
    if (/^R__/i.test(fileName)) return 'Repeatable migration';
    return null;
}

function parseCodeGenSection(codegenRaw, codegenMasked, baseLineOffset) {
    const newlines = buildNewlineIndex(codegenMasked);
    const hasSubstantiveSql = /\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|GRANT|EXEC|EXECUTE|MERGE)\b/i.test(codegenMasked);

    const entityInsertBlocksRaw = [];
    const entityInsertRe = /\bINSERT\s+INTO\s+(?:[^\s(]*?[.\]"`])?(?:\[Entity\]|"Entity"|`Entity`|Entity)\s*\(/gi;
    let m;
    while ((m = entityInsertRe.exec(codegenMasked)) !== null) {
        const end = findStatementEndInBatch(codegenMasked, m.index);
        entityInsertBlocksRaw.push(codegenRaw.slice(m.index, end));
    }

    const entityFieldInserts = [];
    const efInsertRe = /\bINSERT\s+INTO\s+(?:[^\s(]*?[.\]"`])?(?:\[EntityField\]|"EntityField"|`EntityField`|EntityField)\s*\(/gi;
    while ((m = efInsertRe.exec(codegenMasked)) !== null) {
        const openCols = m.index + m[0].length - 1;
        const cols = parseBalancedParenList(codegenMasked, openCols);
        if (!cols) continue;
        const bareCols = cols.items.map((c) => unquoteIdentifier(c).toLowerCase());
        const nameIdx = bareCols.indexOf('name');
        const seqIdx = bareCols.indexOf('sequence');
        const afterCols = skipWhitespace(codegenMasked, cols.end);
        if (/^VALUES\b/i.test(codegenMasked.slice(afterCols, afterCols + 7))) {
            let cursor = afterCols + 'VALUES'.length;
            for (;;) {
                const openTuple = skipWhitespace(codegenMasked, cursor);
                if (codegenMasked[openTuple] !== '(') break;
                const tuple = parseBalancedParenList(codegenMasked, openTuple);
                if (!tuple) break;
                let columnName = null;
                if (nameIdx !== -1 && nameIdx < tuple.starts.length) {
                    const rawVal = codegenRaw.slice(tuple.starts[nameIdx], tuple.ends[nameIdx]).trim();
                    const strMatch = /^N?'((?:[^']|'')*)'/i.exec(rawVal);
                    if (strMatch) columnName = strMatch[1].replace(/''/g, "'");
                }
                let hasLiteralSequence = false;
                let hasApplyTimeSequence = false;
                if (seqIdx !== -1 && seqIdx < tuple.items.length) {
                    const seqVal = tuple.items[seqIdx];
                    if (/^\(?\s*[+-]?\d+\s*\)?$/.test(seqVal)) hasLiteralSequence = true;
                    else if (/COALESCE\s*\(\s*MAX\s*\(/i.test(seqVal) || /ISNULL\s*\(\s*MAX\s*\(/i.test(seqVal)) {
                        hasApplyTimeSequence = true;
                    }
                }
                entityFieldInserts.push({
                    columnName,
                    hasLiteralSequence,
                    hasApplyTimeSequence,
                    lineNumber: baseLineOffset + lineNumberAtOffset(newlines, openTuple),
                });
                cursor = tuple.end;
                const sep = skipWhitespace(codegenMasked, cursor);
                if (codegenMasked[sep] !== ',') break;
                cursor = sep + 1;
            }
            efInsertRe.lastIndex = cursor;
        }
    }

    const entityFieldUpdateBlocksRaw = [];
    const efUpdateRe = /\bUPDATE\s+(?:[^\s(]*?[.\]"`])?(?:\[EntityField\]|"EntityField"|`EntityField`|\bEntityField\b)/gi;
    while ((m = efUpdateRe.exec(codegenMasked)) !== null) {
        const end = findStatementEndInBatch(codegenMasked, m.index);
        entityFieldUpdateBlocksRaw.push(codegenRaw.slice(m.index, end));
    }

    const hasSpUpdateExistingEntityFields = /\bspUpdateExistingEntityFieldsFromSchema\b/i.test(codegenMasked);
    const hasEntityFieldValueSync =
        /\b(?:INSERT\s+INTO|UPDATE|DELETE\s+(?:FROM\s+)?|MERGE\s+(?:INTO\s+)?)\s*(?:[^\s(]*?[.\]"`])?(?:\[EntityFieldValue\]|"EntityFieldValue"|`EntityFieldValue`|\bEntityFieldValue\b)/i.test(codegenMasked);

    const views = [];
    const procs = [];
    const triggerNamesLower = new Set();
    const grantedObjectsLower = new Set();
    const batches = splitBatchesWithOffsets(codegenMasked);
    const createViewRe = new RegExp(`\\bCREATE\\s+(?:OR\\s+ALTER\\s+)?VIEW\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
    const createProcRe = new RegExp(`\\bCREATE\\s+(?:OR\\s+ALTER\\s+)?PROC(?:EDURE)?\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
    const createTriggerRe = new RegExp(`\\bCREATE\\s+(?:OR\\s+ALTER\\s+)?TRIGGER\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
    const grantRe = new RegExp(`\\bGRANT\\s+(?:SELECT|EXECUTE|INSERT|UPDATE|DELETE|ALL)\\s+ON\\s+(?:OBJECT::)?(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
    const fromTableRe = new RegExp(`\\bFROM\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');

    for (const batch of batches) {
        createViewRe.lastIndex = 0;
        while ((m = createViewRe.exec(batch.text)) !== null) {
            const { objectName } = parseQualifiedObjectName(m[1]);
            const bodyMasked = batch.text.slice(m.index);
            const fromTablesLower = new Set();
            fromTableRe.lastIndex = 0;
            let fm;
            while ((fm = fromTableRe.exec(bodyMasked)) !== null) {
                const parsedFrom = parseQualifiedObjectName(fm[1]);
                if (parsedFrom.objectName) fromTablesLower.add(parsedFrom.objectName.toLowerCase());
            }
            const usesWildcardSelect =
                /\bSELECT\b[\s\S]*?(?:\b[A-Za-z_][A-Za-z0-9_]*\s*\.\s*\*|(?<![A-Za-z0-9_])\*)\s*(?:,|\bFROM\b)/i.test(bodyMasked);
            views.push({ viewName: objectName, bodyMasked, fromTablesLower, usesWildcardSelect });
        }
        createProcRe.lastIndex = 0;
        while ((m = createProcRe.exec(batch.text)) !== null) {
            const { objectName } = parseQualifiedObjectName(m[1]);
            procs.push({ procName: objectName, bodyMasked: batch.text.slice(m.index) });
        }
        createTriggerRe.lastIndex = 0;
        while ((m = createTriggerRe.exec(batch.text)) !== null) {
            const { objectName } = parseQualifiedObjectName(m[1]);
            if (objectName) triggerNamesLower.add(objectName.toLowerCase());
        }
        grantRe.lastIndex = 0;
        while ((m = grantRe.exec(batch.text)) !== null) {
            const { objectName } = parseQualifiedObjectName(m[1]);
            if (objectName) grantedObjectsLower.add(objectName.toLowerCase());
        }
    }

    return {
        hasSubstantiveSql,
        entityInsertBlocksRaw,
        entityFieldInserts,
        entityFieldUpdateBlocksRaw,
        hasSpUpdateExistingEntityFields,
        hasEntityFieldValueSync,
        views,
        procs,
        triggerNamesLower,
        grantedObjectsLower,
    };
}

function parseHandDdlSection(handRaw, handMasked) {
    const rawLines = handRaw.split(/\r?\n/);
    const newlines = buildNewlineIndex(handMasked);
    const notReqMatch = CODEGEN_NOT_REQUIRED_RE.exec(handRaw);
    const codegenNotRequiredReason = notReqMatch ? notReqMatch[1].trim() : null;
    const fileHasVirtualEntity = VIRTUAL_ENTITY_RE.test(handRaw);
    const fileHasNonValueListCheck = NON_VALUELIST_CHECK_RE.test(handRaw);

    const createdTables = [];
    const createdTableNamesLower = new Set();
    const addedColumns = [];
    const alteredColumns = [];
    const checkConstraints = [];
    const breakingOperations = [];

    const batches = splitBatchesWithOffsets(handMasked);
    const createTableRe = new RegExp(`\\bCREATE\\s+TABLE\\s+(${SQL_QUALIFIED_NAME_SRC})\\s*\\(`, 'gi');
    const alterTableRe = new RegExp(`\\bALTER\\s+TABLE\\s+(${SQL_QUALIFIED_NAME_SRC})(?=\\s|;|$)`, 'gi');
    const dropTableRe = new RegExp(`\\bDROP\\s+TABLE\\s+(?:IF\\s+EXISTS\\s+)?(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
    const spRenameRe = /\b(?:EXEC(?:UTE)?\s+)?(?:(?:dbo|sys)\.)?(?:\[sp_rename\]|\bsp_rename\b)/gi;

    for (const batch of batches) {
        let m;
        createTableRe.lastIndex = 0;
        while ((m = createTableRe.exec(batch.text)) !== null) {
            const { schemaName, objectName } = parseQualifiedObjectName(m[1]);
            if (!objectName || isTempTableName(objectName)) continue;
            const globalOffset = batch.startOffset + m.index;
            const lineNumber = lineNumberAtOffset(newlines, globalOffset);
            const openParen = m.index + m[0].length - 1;
            const closeParen = findMatchingCloseParen(batch.text, openParen);
            const globalClose = closeParen !== -1 ? batch.startOffset + closeParen + 1 : batch.endOffset;
            const rawSlice = handRaw.slice(globalOffset, globalClose);
            const hasValueListCheck = detectValueListCheckInRawSlice(rawSlice);
            const nonValueListCheckExempt =
                fileHasNonValueListCheck ||
                NON_VALUELIST_CHECK_RE.test(rawSlice) ||
                hasAnnotationNearLine(rawLines, lineNumber, NON_VALUELIST_CHECK_RE);
            const isVirtualEntity =
                fileHasVirtualEntity ||
                VIRTUAL_ENTITY_RE.test(rawSlice) ||
                hasAnnotationNearLine(rawLines, lineNumber, VIRTUAL_ENTITY_RE);
            createdTables.push({ schemaName, tableName: objectName, lineNumber, isVirtualEntity, hasValueListCheck, nonValueListCheckExempt });
            createdTableNamesLower.add(objectName.toLowerCase());
            if (hasValueListCheck) {
                checkConstraints.push({ tableName: objectName, lineNumber, isValueList: true, exempt: nonValueListCheckExempt });
            }
        }

        alterTableRe.lastIndex = 0;
        while ((m = alterTableRe.exec(batch.text)) !== null) {
            const { schemaName, objectName } = parseQualifiedObjectName(m[1]);
            if (!objectName || isTempTableName(objectName)) continue;
            const stmtEndInBatch = findStatementEndInBatch(batch.text, m.index + m[0].length);
            const actionStartInBatch = skipWhitespace(batch.text, m.index + m[0].length);
            const actionMasked = batch.text.slice(actionStartInBatch, stmtEndInBatch);
            const globalStmtStart = batch.startOffset + m.index;
            const globalActionStart = batch.startOffset + actionStartInBatch;
            const globalStmtEnd = batch.startOffset + stmtEndInBatch;
            const stmtRaw = handRaw.slice(globalStmtStart, globalStmtEnd);
            const stmtLine = lineNumberAtOffset(newlines, globalStmtStart);
            const tableCreatedInSameMigration = createdTableNamesLower.has(objectName.toLowerCase());

            const dropColMatch = /\bDROP\s+COLUMN\s+(?:IF\s+EXISTS\s+)?([\s\S]+)/i.exec(actionMasked);
            if (dropColMatch) {
                for (const colItem of splitTopLevelCommas(dropColMatch[1])) {
                    const colName = extractFirstIdentifier(colItem.segment);
                    if (colName && !isMjSystemColumn(colName)) {
                        breakingOperations.push({ kind: 'DropColumn', tableName: objectName, columnName: colName, lineNumber: stmtLine });
                    }
                }
                continue;
            }

            const alterColMatch = new RegExp(`^ALTER\\s+COLUMN\\s+(${SQL_OBJ_PART})`, 'i').exec(actionMasked.trim());
            if (alterColMatch) {
                const colName = unquoteIdentifier(alterColMatch[1]);
                if (colName && !isMjSystemColumn(colName)) {
                    alteredColumns.push({ schemaName, tableName: objectName, columnName: colName, lineNumber: stmtLine });
                }
                continue;
            }

            const addClauseMatch = /^(?:WITH\s+(?:CHECK|NOCHECK)\s+)?ADD\b/i.exec(actionMasked);
            if (addClauseMatch) {
                const addBodyOffset = addClauseMatch[0].length;
                const addBodyMasked = actionMasked.slice(addBodyOffset);
                const stmtNonValueListExempt =
                    fileHasNonValueListCheck ||
                    NON_VALUELIST_CHECK_RE.test(stmtRaw) ||
                    hasAnnotationNearLine(rawLines, stmtLine, NON_VALUELIST_CHECK_RE);
                for (const item of splitTopLevelCommas(addBodyMasked)) {
                    const segTrimmed = item.segment.trim();
                    if (!segTrimmed) continue;
                    const itemGlobalStart = globalActionStart + addBodyOffset + item.startOffset;
                    const itemGlobalEnd = globalActionStart + addBodyOffset + item.endOffset;
                    const itemRaw = handRaw.slice(itemGlobalStart, itemGlobalEnd);
                    const itemLine = lineNumberAtOffset(newlines, itemGlobalStart);
                    const itemNonValueListExempt =
                        stmtNonValueListExempt ||
                        NON_VALUELIST_CHECK_RE.test(itemRaw) ||
                        hasAnnotationNearLine(rawLines, itemLine, NON_VALUELIST_CHECK_RE);

                    if (/^(?:CONSTRAINT|CHECK|PRIMARY\s+KEY|UNIQUE|FOREIGN\s+KEY|DEFAULT)\b/i.test(segTrimmed)) {
                        if (/\bCHECK\s*\(/i.test(segTrimmed)) {
                            checkConstraints.push({
                                tableName: objectName,
                                lineNumber: itemLine,
                                isValueList: detectValueListCheckInRawSlice(itemRaw),
                                exempt: itemNonValueListExempt,
                            });
                        }
                        continue;
                    }
                    const colName = extractFirstIdentifier(segTrimmed);
                    if (!colName || isMjSystemColumn(colName)) continue;
                    const hasNotNull = /\bNOT\s+NULL\b/i.test(segTrimmed);
                    const hasDefault = /\bDEFAULT\b/i.test(segTrimmed);
                    const isNotNullWithoutDefault = hasNotNull && !hasDefault && !tableCreatedInSameMigration;
                    const hasValueListCheck = detectValueListCheckInRawSlice(itemRaw);
                    addedColumns.push({ schemaName, tableName: objectName, columnName: colName, lineNumber: itemLine, isNotNullWithoutDefault, hasValueListCheck, nonValueListCheckExempt: itemNonValueListExempt });
                    if (hasValueListCheck) {
                        checkConstraints.push({ tableName: objectName, lineNumber: itemLine, isValueList: true, exempt: itemNonValueListExempt });
                    }
                    if (isNotNullWithoutDefault) {
                        breakingOperations.push({ kind: 'NotNullWithoutDefault', tableName: objectName, columnName: colName, lineNumber: itemLine });
                    }
                }
            }
        }

        dropTableRe.lastIndex = 0;
        while ((m = dropTableRe.exec(batch.text)) !== null) {
            const { objectName } = parseQualifiedObjectName(m[1]);
            if (!objectName || isTempTableName(objectName)) continue;
            breakingOperations.push({ kind: 'DropTable', tableName: objectName, lineNumber: lineNumberAtOffset(newlines, batch.startOffset + m.index) });
        }

        spRenameRe.lastIndex = 0;
        while ((m = spRenameRe.exec(batch.text)) !== null) {
            breakingOperations.push({ kind: 'SpRename', lineNumber: lineNumberAtOffset(newlines, batch.startOffset + m.index) });
        }
    }

    const hasEntityAffectingDdl =
        createdTables.length > 0 ||
        addedColumns.length > 0 ||
        alteredColumns.length > 0 ||
        checkConstraints.some((c) => c.isValueList && !c.exempt) ||
        breakingOperations.some((b) => b.kind === 'DropColumn' || b.kind === 'DropTable');

    return {
        createdTables,
        addedColumns,
        alteredColumns,
        checkConstraints,
        breakingOperations,
        hasEntityAffectingDdl,
        codegenNotRequiredReason,
    };
}

/**
 * Pure alignment validator over virtual files (used by both CLI and unit/self tests).
 */
export function validateMigrationCodeGenAlignment({
    changedPaths,
    files,
    config = {},
    repoHasPgMigrationsDir,
    repoHasGeneratedEntitiesDir,
}) {
    const startedAt = Date.now();
    const resolvedConfig = {
        mode: config.mode === 'Warn' || config.mode === 'Off' ? config.mode : 'Enforce',
        minBlankLinesBeforeCodeGen:
            typeof config.minBlankLinesBeforeCodeGen === 'number' && Number.isFinite(config.minBlankLinesBeforeCodeGen) && config.minBlankLinesBeforeCodeGen >= 0
                ? Math.trunc(config.minBlankLinesBeforeCodeGen)
                : 50,
        enforceAdditiveSchemaPolicy: config.enforceAdditiveSchemaPolicy !== false,
        enforcePgCounterpartAlignment: config.enforcePgCounterpartAlignment !== false,
        enforceGeneratedTsAlignment: config.enforceGeneratedTsAlignment !== false,
    };

    const tsqlMigrations = [];
    const pgMigrations = [];
    const generatedTsFiles = [];
    const seen = new Set();
    for (const raw of changedPaths) {
        const p = normalizePath(raw);
        if (!p || FIXTURE_DIR_RE.test(p) || seen.has(p)) continue;
        seen.add(p);
        if (TSQL_MIGRATION_PATH_RE.test(p)) tsqlMigrations.push(p);
        else if (PG_MIGRATION_PATH_RE.test(p)) pgMigrations.push(p);
        else if (GENERATED_TS_ENTITY_PATH_RE.test(p)) generatedTsFiles.push(p);
    }

    if (resolvedConfig.mode === 'Off') {
        return {
            applicable: false,
            passed: true,
            mode: 'Off',
            config: resolvedConfig,
            tsqlMigrationsChecked: tsqlMigrations,
            pgMigrationsChecked: pgMigrations,
            generatedTsFilesChecked: generatedTsFiles,
            findings: [],
            blockingReasons: [],
            warnings: [],
            durationMs: Date.now() - startedAt,
            summary: 'Migration <-> CodeGen alignment check disabled (mode=Off).',
        };
    }

    if (tsqlMigrations.length === 0 && pgMigrations.length === 0) {
        return {
            applicable: false,
            passed: true,
            mode: resolvedConfig.mode,
            config: resolvedConfig,
            tsqlMigrationsChecked: [],
            pgMigrationsChecked: [],
            generatedTsFilesChecked: generatedTsFiles,
            findings: [],
            blockingReasons: [],
            warnings: [],
            durationMs: Date.now() - startedAt,
            summary: 'No changed migrations to check.',
        };
    }

    const severity = resolvedConfig.mode === 'Warn' ? 'warning' : 'error';
    const fileMapLower = new Map();
    for (const f of files) fileMapLower.set(normalizePath(f.path).toLowerCase(), f.content);

    const hasPgDir =
        repoHasPgMigrationsDir !== undefined
            ? repoHasPgMigrationsDir
            : pgMigrations.length > 0 || files.some((f) => /(?:^|\/)migrations-pg\//i.test(normalizePath(f.path)));
    const hasGenTsDir =
        repoHasGeneratedEntitiesDir !== undefined
            ? repoHasGeneratedEntitiesDir
            : generatedTsFiles.length > 0 || files.some((f) => GENERATED_TS_ENTITY_PATH_RE.test(normalizePath(f.path)));

    const findings = [];
    const tablesForTs = new Set();
    const colsForTs = new Set();
    let anyNeedsGenTs = false;

    for (const filePath of tsqlMigrations) {
        const rawSql = fileMapLower.get(filePath.toLowerCase());
        if (rawSql === undefined) {
            findings.push({
                invariant: 'MandatoryCodeGenPresence',
                code: 'MIGRATION_FILE_UNREADABLE',
                severity,
                filePath,
                message: `Changed T-SQL migration '${filePath}' could not be read from disk.`,
            });
            continue;
        }

        const rawLines = rawSql.split(/\r?\n/);
        const bannerLineIndex = rawLines.findIndex((l) => CODEGEN_BANNER_LINE_RE.test(l));
        const hasBanner = bannerLineIndex !== -1;
        let headerStart = bannerLineIndex;
        if (hasBanner && bannerLineIndex > 0 && COMMENT_SEPARATOR_LINE_RE.test(rawLines[bannerLineIndex - 1])) {
            headerStart = bannerLineIndex - 1;
        }

        let handRaw = rawSql;
        let codegenRaw = '';
        if (hasBanner) {
            let blanks = 0;
            for (let i = headerStart - 1; i >= 0; i -= 1) {
                if (/^\s*$/.test(rawLines[i])) blanks += 1;
                else break;
            }
            handRaw = rawLines.slice(0, headerStart).join('\n');
            codegenRaw = rawLines.slice(bannerLineIndex).join('\n');
            if (handRaw.trim().length > 0 && blanks < resolvedConfig.minBlankLinesBeforeCodeGen) {
                findings.push({
                    invariant: 'FileAnatomyAndSeparation',
                    code: 'ANATOMY_INSUFFICIENT_BLANK_LINES',
                    severity,
                    filePath,
                    lineNumber: headerStart + 1,
                    message: `Only ${blanks} consecutive blank line(s) precede the CodeGen banner header (minimum required: ${resolvedConfig.minBlankLinesBeforeCodeGen}).`,
                });
            }
        }

        const handMasked = stripSqlCommentsAndLiterals(handRaw);
        const codegenMasked = hasBanner ? stripSqlCommentsAndLiterals(codegenRaw) : '';

        // Invariant 1b: CodeGen-owned objects above banner
        const handRawLines = handRaw.split(/\r?\n/);
        const handNewlines = buildNewlineIndex(handMasked);
        const routineRe = new RegExp(`\\bCREATE\\s+(?:OR\\s+ALTER\\s+)?(PROC(?:EDURE)?|VIEW|TRIGGER)\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
        let m;
        while ((m = routineRe.exec(handMasked)) !== null) {
            const kind = m[1].toUpperCase();
            const { objectName } = parseQualifiedObjectName(m[2]);
            const lineNumber = lineNumberAtOffset(handNewlines, m.index);
            const isOwned =
                (kind.startsWith('PROC') && /^sp(?:Create|Update|Delete)[A-Za-z0-9_]+$/i.test(objectName)) ||
                (kind === 'VIEW' && /^vw[A-Za-z0-9_]+$/i.test(objectName)) ||
                (kind === 'TRIGGER' && /^trgUpdate[A-Za-z0-9_]+$/i.test(objectName));
            if (isOwned && !hasAnnotationNearLine(handRawLines, lineNumber, CODEGEN_OVERRIDE_OK_RE)) {
                findings.push({
                    invariant: 'FileAnatomyAndSeparation',
                    code: 'ANATOMY_CODEGEN_OBJECT_ABOVE_BANNER',
                    severity,
                    filePath,
                    lineNumber,
                    message: `CodeGen-owned ${kind} '${objectName}' is placed above the CodeGen banner without '-- codegen-override-ok'.`,
                });
            }
        }

        // Invariant 1c: Hand DDL below banner
        if (hasBanner) {
            const cgNewlines = buildNewlineIndex(codegenMasked);
            const createTableRe = new RegExp(`\\bCREATE\\s+TABLE\\s+(${SQL_QUALIFIED_NAME_SRC})`, 'gi');
            const alterTableRe = new RegExp(`\\bALTER\\s+TABLE\\s+(${SQL_QUALIFIED_NAME_SRC})(?=\\s|;|$)`, 'gi');
            const createIndexRe = new RegExp(`\\bCREATE\\s+(?:UNIQUE\\s+)?(?:(?:NON)?CLUSTERED\\s+)?INDEX\\s+(${SQL_OBJ_PART})`, 'gi');
            const extPropRe = /\b(?:EXEC(?:UTE)?\s+)?(?:sys\.)?sp_addextendedproperty\b/gi;
            for (const batch of splitBatchesWithOffsets(codegenMasked)) {
                createTableRe.lastIndex = 0;
                while ((m = createTableRe.exec(batch.text)) !== null) {
                    const { objectName } = parseQualifiedObjectName(m[1]);
                    if (objectName && !isTempTableName(objectName)) {
                        findings.push({
                            invariant: 'FileAnatomyAndSeparation',
                            code: 'ANATOMY_HAND_DDL_BELOW_BANNER',
                            severity,
                            filePath,
                            lineNumber: bannerLineIndex + lineNumberAtOffset(cgNewlines, batch.startOffset + m.index),
                            message: `Hand DDL 'CREATE TABLE ${objectName}' appears below the CodeGen banner.`,
                        });
                    }
                }
                alterTableRe.lastIndex = 0;
                while ((m = alterTableRe.exec(batch.text)) !== null) {
                    const { objectName } = parseQualifiedObjectName(m[1]);
                    if (!objectName || isTempTableName(objectName)) continue;
                    const stmtEnd = findStatementEndInBatch(batch.text, m.index + m[0].length);
                    const action = batch.text.slice(m.index + m[0].length, stmtEnd);
                    if (/(?:__mj_CreatedAt|__mj_UpdatedAt|__mj_DeletedAt)/i.test(action) && !/\bDROP\s+COLUMN\b/i.test(action)) continue;
                    if (/\b(?:ADD|ALTER\s+COLUMN|DROP)\b/i.test(action)) {
                        findings.push({
                            invariant: 'FileAnatomyAndSeparation',
                            code: 'ANATOMY_HAND_DDL_BELOW_BANNER',
                            severity,
                            filePath,
                            lineNumber: bannerLineIndex + lineNumberAtOffset(cgNewlines, batch.startOffset + m.index),
                            message: `Hand DDL 'ALTER TABLE ${objectName}' appears below the CodeGen banner.`,
                        });
                    }
                }
                createIndexRe.lastIndex = 0;
                while ((m = createIndexRe.exec(batch.text)) !== null) {
                    const idxName = unquoteIdentifier(m[1]);
                    if (!/^IDX_AUTO_MJ_FKEY_/i.test(idxName)) {
                        findings.push({
                            invariant: 'FileAnatomyAndSeparation',
                            code: 'ANATOMY_HAND_DDL_BELOW_BANNER',
                            severity,
                            filePath,
                            lineNumber: bannerLineIndex + lineNumberAtOffset(cgNewlines, batch.startOffset + m.index),
                            message: `Hand-written index '${idxName}' appears below the CodeGen banner.`,
                        });
                    }
                }
                extPropRe.lastIndex = 0;
                while ((m = extPropRe.exec(batch.text)) !== null) {
                    findings.push({
                        invariant: 'FileAnatomyAndSeparation',
                        code: 'ANATOMY_HAND_DDL_BELOW_BANNER',
                        severity,
                        filePath,
                        lineNumber: bannerLineIndex + lineNumberAtOffset(cgNewlines, batch.startOffset + m.index),
                        message: `Hand-written 'sp_addextendedproperty' appears below the CodeGen banner.`,
                    });
                }
            }
        }

        const handDdl = parseHandDdlSection(handRaw, handMasked);

        // Invariant 5: Additive Schema Guard
        if (resolvedConfig.enforceAdditiveSchemaPolicy) {
            for (const op of handDdl.breakingOperations) {
                if (op.kind === 'DropTable') {
                    findings.push({ invariant: 'AdditiveSchemaPolicy', code: 'ADDITIVE_POLICY_DROP_TABLE', severity, filePath, lineNumber: op.lineNumber, message: `Breaking 'DROP TABLE ${op.tableName}' violates PUBLISH_NO_BREAK_POLICY.md.` });
                } else if (op.kind === 'DropColumn') {
                    findings.push({ invariant: 'AdditiveSchemaPolicy', code: 'ADDITIVE_POLICY_DROP_COLUMN', severity, filePath, lineNumber: op.lineNumber, message: `Breaking 'DROP COLUMN ${op.columnName}' on '${op.tableName}' violates PUBLISH_NO_BREAK_POLICY.md.` });
                } else if (op.kind === 'SpRename') {
                    findings.push({ invariant: 'AdditiveSchemaPolicy', code: 'ADDITIVE_POLICY_SP_RENAME', severity, filePath, lineNumber: op.lineNumber, message: `Breaking 'sp_rename' violates PUBLISH_NO_BREAK_POLICY.md.` });
                } else if (op.kind === 'NotNullWithoutDefault') {
                    findings.push({ invariant: 'AdditiveSchemaPolicy', code: 'ADDITIVE_POLICY_NOT_NULL_WITHOUT_DEFAULT', severity, filePath, lineNumber: op.lineNumber, message: `Breaking 'ALTER TABLE ${op.tableName} ADD ${op.columnName} ... NOT NULL' without DEFAULT violates PUBLISH_NO_BREAK_POLICY.md.` });
                }
            }
        }

        const exemptReason = isExemptMigrationFileName(filePath) ?? handDdl.codegenNotRequiredReason;
        const exempt = exemptReason !== null;

        if (!exempt && handDdl.hasEntityAffectingDdl) {
            anyNeedsGenTs = true;
            for (const t of handDdl.createdTables) tablesForTs.add(t.tableName);
            for (const c of handDdl.addedColumns) colsForTs.add(c.columnName);

            if (!hasBanner) {
                findings.push({
                    invariant: 'MandatoryCodeGenPresence',
                    code: 'CODEGEN_SECTION_MISSING',
                    severity,
                    filePath,
                    message: `Entity-affecting DDL found (${handDdl.createdTables.length} CREATE TABLE, ${handDdl.addedColumns.length} added column(s)) without '-- GENERATED BY MemberJunction CodeGen' section.`,
                });
            } else {
                const cg = parseCodeGenSection(codegenRaw, codegenMasked, bannerLineIndex);
                if (!cg.hasSubstantiveSql) {
                    findings.push({
                        invariant: 'MandatoryCodeGenPresence',
                        code: 'CODEGEN_SECTION_EMPTY',
                        severity,
                        filePath,
                        lineNumber: bannerLineIndex + 1,
                        message: `CodeGen banner is present but contains no substantive SQL statements.`,
                    });
                } else {
                    const createdLower = new Set(handDdl.createdTables.map((t) => t.tableName.toLowerCase()));

                    for (const ef of cg.entityFieldInserts) {
                        if (ef.hasLiteralSequence) {
                            findings.push({
                                invariant: 'DdlCodeGenCoverageMatch',
                                code: 'CODEGEN_ENTITYFIELD_LITERAL_SEQUENCE',
                                severity,
                                filePath,
                                lineNumber: ef.lineNumber,
                                message: `EntityField INSERT${ef.columnName ? ` for '${ef.columnName}'` : ''} uses a literal Sequence instead of apply-time COALESCE(MAX([Sequence]), 0).`,
                            });
                        }
                    }

                    for (const tbl of handDdl.createdTables) {
                        const tName = tbl.tableName;
                        const tLower = tName.toLowerCase();
                        const quotedTableRe = new RegExp(`'${escapeRegExp(tName)}'`, 'i');
                        if (!cg.entityInsertBlocksRaw.some((b) => quotedTableRe.test(b))) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_ENTITY_INSERT', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing an Entity metadata INSERT in the CodeGen section.` });
                        }
                        if (cg.entityFieldInserts.length === 0) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_ENTITYFIELD_INSERT', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing EntityField metadata INSERTs in the CodeGen section.` });
                        }
                        const matchingViews = cg.views.filter((v) => v.fromTablesLower.has(tLower) || matchesViewNameForTable(v.viewName, tName));
                        if (matchingViews.length === 0) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_BASE_VIEW', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing a generated base view in the CodeGen section.` });
                        }
                        if (!tbl.isVirtualEntity) {
                            for (const procName of [`spCreate${tName}`, `spUpdate${tName}`, `spDelete${tName}`]) {
                                if (!cg.procs.some((p) => p.procName.toLowerCase() === procName.toLowerCase())) {
                                    findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_CRUD_PROC', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing generated procedure '${procName}'.` });
                                }
                            }
                            if (!cg.triggerNamesLower.has(`trgupdate${tLower}`)) {
                                findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_UPDATE_TRIGGER', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing generated trigger 'trgUpdate${tName}'.` });
                            }
                        }
                        const viewNamesLower = new Set(matchingViews.map((v) => v.viewName.toLowerCase()));
                        const procNamesLower = new Set([`spcreate${tLower}`, `spupdate${tLower}`, `spdelete${tLower}`]);
                        const hasGrant = Array.from(cg.grantedObjectsLower).some((o) => viewNamesLower.has(o) || procNamesLower.has(o) || matchesViewNameForTable(o, tName));
                        if (!hasGrant) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_GRANTS', severity, filePath, lineNumber: tbl.lineNumber, message: `New table '${tName}' is missing GRANT permissions in the CodeGen section.` });
                        }
                    }

                    for (const col of handDdl.addedColumns) {
                        const tName = col.tableName;
                        const tLower = tName.toLowerCase();
                        if (createdLower.has(tLower)) continue;
                        const cName = col.columnName;
                        const cLower = cName.toLowerCase();
                        const escapedCol = escapeRegExp(cName);
                        const matchingEfInserts = cg.entityFieldInserts.filter((ef) => ef.columnName && ef.columnName.toLowerCase() === cLower);
                        const hasEfUpdate = cg.entityFieldUpdateBlocksRaw.some((b) => new RegExp(`'${escapedCol}'`, 'i').test(b));
                        if (matchingEfInserts.length === 0 && !hasEfUpdate) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_COLUMN_ENTITYFIELD', severity, filePath, lineNumber: col.lineNumber, message: `Added column '${tName}.${cName}' has no matching EntityField INSERT/UPDATE in CodeGen.` });
                        } else if (matchingEfInserts.length > 0 && !matchingEfInserts.some((ef) => ef.hasApplyTimeSequence) && !matchingEfInserts.some((ef) => ef.hasLiteralSequence)) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_ENTITYFIELD_SEQUENCE_NOT_APPLY_TIME', severity, filePath, lineNumber: matchingEfInserts[0].lineNumber, message: `EntityField INSERT for '${tName}.${cName}' does not use apply-time COALESCE(MAX([Sequence]), 0).` });
                        }
                        const matchingViews = cg.views.filter((v) => v.fromTablesLower.has(tLower) || matchesViewNameForTable(v.viewName, tName));
                        const colInViewRe = new RegExp(`(?:\\[${escapedCol}\\]|\\b${escapedCol}\\b)`, 'i');
                        if (matchingViews.length === 0 || !matchingViews.some((v) => v.usesWildcardSelect || colInViewRe.test(v.bodyMasked))) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_COLUMN_IN_VIEW', severity, filePath, lineNumber: col.lineNumber, message: `Added column '${tName}.${cName}' is not covered by a regenerated base view for '${tName}'.` });
                        }
                        const paramRe = new RegExp(`@${escapedCol}\\b`, 'i');
                        for (const prefix of ['spCreate', 'spUpdate']) {
                            const expectedProc = `${prefix}${tName}`;
                            const proc = cg.procs.find((p) => p.procName.toLowerCase() === expectedProc.toLowerCase());
                            if (!proc) {
                                findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_REGENERATED_PROC', severity, filePath, lineNumber: col.lineNumber, message: `Added column '${tName}.${cName}' requires regenerated '${expectedProc}'.` });
                            } else if (!paramRe.test(proc.bodyMasked)) {
                                findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_PROC_MISSING_COLUMN_PARAM', severity, filePath, lineNumber: col.lineNumber, message: `Regenerated '${expectedProc}' does not reference '@${cName}'.` });
                            }
                        }
                    }

                    for (const col of handDdl.alteredColumns) {
                        const tName = col.tableName;
                        const tLower = tName.toLowerCase();
                        if (createdLower.has(tLower)) continue;
                        const cName = col.columnName;
                        const escapedCol = escapeRegExp(cName);
                        const hasEfMetaUpdate =
                            cg.hasSpUpdateExistingEntityFields ||
                            cg.entityFieldUpdateBlocksRaw.some((b) => new RegExp(`'${escapedCol}'`, 'i').test(b)) ||
                            cg.entityFieldInserts.some((ef) => ef.columnName && ef.columnName.toLowerCase() === cName.toLowerCase());
                        if (!hasEfMetaUpdate) {
                            findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_ALTERED_COLUMN_METADATA', severity, filePath, lineNumber: col.lineNumber, message: `Altered column '${tName}.${cName}' has no matching EntityField UPDATE in CodeGen.` });
                        }
                        const paramRe = new RegExp(`@${escapedCol}\\b`, 'i');
                        for (const prefix of ['spCreate', 'spUpdate']) {
                            const expectedProc = `${prefix}${tName}`;
                            const proc = cg.procs.find((p) => p.procName.toLowerCase() === expectedProc.toLowerCase());
                            if (!proc || !paramRe.test(proc.bodyMasked)) {
                                findings.push({ invariant: 'DdlCodeGenCoverageMatch', code: 'CODEGEN_MISSING_ALTERED_COLUMN_PROC', severity, filePath, lineNumber: col.lineNumber, message: `Altered column '${tName}.${cName}' requires regenerated '${expectedProc}' referencing '@${cName}'.` });
                            }
                        }
                    }

                    const activeValueListChecks = handDdl.checkConstraints.filter((c) => c.isValueList && !c.exempt);
                    if (activeValueListChecks.length > 0 && !cg.hasEntityFieldValueSync) {
                        findings.push({
                            invariant: 'DdlCodeGenCoverageMatch',
                            code: 'CODEGEN_MISSING_ENTITYFIELDVALUE_SYNC',
                            severity,
                            filePath,
                            lineNumber: activeValueListChecks[0].lineNumber,
                            message: `Value-list CHECK constraint on '${activeValueListChecks[0].tableName}' has no EntityFieldValue sync statements in CodeGen (or annotate '-- non-valuelist-check').`,
                        });
                    }
                }
            }
        }

        // Invariant 4a: PG counterpart alignment
        if (resolvedConfig.enforcePgCounterpartAlignment && hasPgDir && !PG_NOT_REQUIRED_RE.test(rawSql)) {
            const pgPath = filePath.replace(/(^|\/)migrations\//i, '$1migrations-pg/').replace(/\.sql$/i, '.pg.sql');
            const pgOnlyPath = filePath.replace(/(^|\/)migrations\//i, '$1migrations-pg/').replace(/\.sql$/i, '.pg-only');
            if (!fileMapLower.has(pgOnlyPath.toLowerCase())) {
                const pgContent = fileMapLower.get(pgPath.toLowerCase());
                if (pgContent === undefined) {
                    findings.push({
                        invariant: 'CrossFilePrLockstep',
                        code: 'CROSS_FILE_MISSING_PG_COUNTERPART',
                        severity,
                        filePath,
                        message: `T-SQL migration '${filePath}' is missing its PostgreSQL counterpart '${pgPath}'.`,
                    });
                } else {
                    const tablesToCheck = new Set([
                        ...handDdl.createdTables.map((t) => t.tableName),
                        ...handDdl.addedColumns.map((c) => c.tableName),
                        ...handDdl.alteredColumns.map((c) => c.tableName),
                    ]);
                    for (const tName of tablesToCheck) {
                        if (!new RegExp(`(?:"|'|\\b)${escapeRegExp(tName)}(?:"|'|\\b)`, 'i').test(pgContent)) {
                            findings.push({ invariant: 'CrossFilePrLockstep', code: 'CROSS_FILE_PG_MISSING_TABLE', severity, filePath: pgPath, message: `PostgreSQL counterpart '${pgPath}' does not reference table '${tName}'.` });
                        }
                    }
                    for (const col of handDdl.addedColumns) {
                        if (!new RegExp(`(?:"|'|\\b)${escapeRegExp(col.columnName)}(?:"|'|\\b)`, 'i').test(pgContent)) {
                            findings.push({ invariant: 'CrossFilePrLockstep', code: 'CROSS_FILE_PG_MISSING_COLUMN', severity, filePath: pgPath, message: `PostgreSQL counterpart '${pgPath}' does not reference added column '${col.tableName}.${col.columnName}'.` });
                        }
                    }
                }
            }
        }
    }

    // Invariant 4b: Generated TS lockstep
    if (resolvedConfig.enforceGeneratedTsAlignment && anyNeedsGenTs && hasGenTsDir) {
        if (generatedTsFiles.length === 0) {
            findings.push({
                invariant: 'CrossFilePrLockstep',
                code: 'CROSS_FILE_MISSING_GENERATED_TS',
                severity,
                filePath: tsqlMigrations[0] ?? 'migrations',
                message: `PR modifies entity-affecting migrations without updating generated TypeScript entities under 'packages/*Entities*/src/generated/' or 'packages/MJCoreEntities/src/generated/'.`,
            });
        } else {
            const loaded = generatedTsFiles.map((p) => fileMapLower.get(p.toLowerCase())).filter((c) => c !== undefined);
            if (loaded.length > 0) {
                const combined = loaded.join('\n');
                for (const tName of tablesForTs) {
                    if (!new RegExp(escapeRegExp(tName), 'i').test(combined)) {
                        findings.push({ invariant: 'CrossFilePrLockstep', code: 'CROSS_FILE_GENERATED_TS_MISSING_TABLE', severity, filePath: generatedTsFiles[0], message: `Changed generated TypeScript entities do not reference new table '${tName}'.` });
                    }
                }
                for (const cName of colsForTs) {
                    if (!new RegExp(`\\b${escapeRegExp(cName)}\\b`, 'i').test(combined)) {
                        findings.push({ invariant: 'CrossFilePrLockstep', code: 'CROSS_FILE_GENERATED_TS_MISSING_COLUMN', severity, filePath: generatedTsFiles[0], message: `Changed generated TypeScript entities do not reference added column '${cName}'.` });
                    }
                }
            }
        }
    }

    const blockingReasons = findings
        .filter((f) => f.severity === 'error')
        .map((f) => `[${f.code}] ${f.filePath}${f.lineNumber ? `:${f.lineNumber}` : ''}: ${f.message}`);
    const warnings = findings
        .filter((f) => f.severity === 'warning')
        .map((f) => `[${f.code}] ${f.filePath}${f.lineNumber ? `:${f.lineNumber}` : ''}: ${f.message}`);
    const passed = resolvedConfig.mode === 'Warn' || blockingReasons.length === 0;
    const durationMs = Date.now() - startedAt;

    return {
        applicable: true,
        passed,
        mode: resolvedConfig.mode,
        config: resolvedConfig,
        tsqlMigrationsChecked: tsqlMigrations,
        pgMigrationsChecked: pgMigrations,
        generatedTsFilesChecked: generatedTsFiles,
        findings,
        blockingReasons,
        warnings,
        durationMs,
        summary: passed
            ? `Migration <-> CodeGen alignment passed (${tsqlMigrations.length} T-SQL, ${pgMigrations.length} PG, ${generatedTsFiles.length} generated TS) in ${durationMs}ms.`
            : `Migration <-> CodeGen alignment failed with ${blockingReasons.length} violation(s) in ${durationMs}ms.`,
    };
}

// ─── Self-test fixtures ────────────────────────────────────────────────────────────────────────

const BLANK_52 = '\n'.repeat(53);

const VALID_NEW_TABLE_SQL = `CREATE TABLE \${flyway:defaultSchema}.[Widget] (
    [ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
    [Status] NVARCHAR(20) NOT NULL CHECK ([Status] IN (N'Active', N'Archived'))
);
GO${BLANK_52}-- =============================================================================
-- GENERATED BY MemberJunction CodeGen — DO NOT EDIT BY HAND
-- =============================================================================
INSERT INTO [\${mjSchema}].[Entity] ([ID], [Name], [BaseTable]) VALUES ('11111111-1111-1111-1111-111111111111', 'Widgets', 'Widget');
INSERT INTO [\${mjSchema}].[EntityField] ([ID], [EntityID], [Sequence], [Name]) VALUES ('22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', (SELECT COALESCE(MAX([Sequence]), 0) + 1 FROM [\${mjSchema}].[EntityField] WHERE [EntityID] = '11111111-1111-1111-1111-111111111111'), 'Status');
INSERT INTO [\${mjSchema}].[EntityFieldValue] ([ID], [EntityFieldID], [Sequence], [Value]) VALUES ('33333333-3333-3333-3333-333333333333', '22222222-2222-2222-2222-222222222222', 1, 'Active');
GO
CREATE VIEW [\${flyway:defaultSchema}].[vwWidgets] AS SELECT w.* FROM [\${flyway:defaultSchema}].[Widget] AS w;
GO
GRANT SELECT ON [\${flyway:defaultSchema}].[vwWidgets] TO [cdp_UI];
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spCreateWidget] @ID uniqueidentifier, @Status nvarchar(20) AS BEGIN SELECT 1; END;
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spUpdateWidget] @ID uniqueidentifier, @Status nvarchar(20) AS BEGIN SELECT 1; END;
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spDeleteWidget] @ID uniqueidentifier AS BEGIN SELECT 1; END;
GO
CREATE TRIGGER [\${flyway:defaultSchema}].trgUpdateWidget ON [\${flyway:defaultSchema}].[Widget] AFTER UPDATE AS BEGIN SET NOCOUNT ON; END;
GO`;

const VALID_PG_SQL = `CREATE TABLE "__mj"."Widget" ("ID" UUID PRIMARY KEY, "Status" VARCHAR(20) NOT NULL);`;
const VALID_GEN_TS = `export class WidgetEntity { get Status(): 'Active' | 'Archived' { return 'Active'; } }`;

export function runSelfTests() {
    const cases = [
        {
            name: 'valid 4-part CREATE TABLE migration with PG + generated TS passes',
            expectPass: true,
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: [
                        'migrations/V202611260001__v1.0.x__Add_Widget.sql',
                        'migrations-pg/V202611260001__v1.0.x__Add_Widget.pg.sql',
                        'packages/Entities/src/generated/entity_subclasses.ts',
                    ],
                    files: [
                        { path: 'migrations/V202611260001__v1.0.x__Add_Widget.sql', content: VALID_NEW_TABLE_SQL },
                        { path: 'migrations-pg/V202611260001__v1.0.x__Add_Widget.pg.sql', content: VALID_PG_SQL },
                        { path: 'packages/Entities/src/generated/entity_subclasses.ts', content: VALID_GEN_TS },
                    ],
                    repoHasPgMigrationsDir: true,
                    repoHasGeneratedEntitiesDir: true,
                }),
        },
        {
            name: 'insufficient blank lines (<50) before CodeGen banner fails',
            expectPass: false,
            expectCode: 'ANATOMY_INSUFFICIENT_BLANK_LINES',
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260001__v1.0.x__Add_Widget.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260001__v1.0.x__Add_Widget.sql',
                            content: VALID_NEW_TABLE_SQL.replace(BLANK_52, '\n\n\n'),
                        },
                    ],
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
        {
            name: 'missing CodeGen section on CREATE TABLE fails',
            expectPass: false,
            expectCode: 'CODEGEN_SECTION_MISSING',
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260001__v1.0.x__Add_Widget.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260001__v1.0.x__Add_Widget.sql',
                            content: `CREATE TABLE dbo.[Widget] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY);`,
                        },
                    ],
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
        {
            name: 'index-only migration without CodeGen banner passes',
            expectPass: true,
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260002__v1.0.x__Add_Index.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260002__v1.0.x__Add_Index.sql',
                            content: `CREATE INDEX [IX_Widget_Status] ON \${flyway:defaultSchema}.[Widget] ([Status]);\nGO`,
                        },
                    ],
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
        {
            name: 'breaking DROP COLUMN rejected under additive policy',
            expectPass: false,
            expectCode: 'ADDITIVE_POLICY_DROP_COLUMN',
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260003__v1.0.x__Drop_Col.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260003__v1.0.x__Drop_Col.sql',
                            content: `-- codegen-not-required: testing additive guard\nALTER TABLE dbo.[Widget] DROP COLUMN [OldCol];`,
                        },
                    ],
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
        {
            name: 'breaking NOT NULL without DEFAULT rejected on existing table',
            expectPass: false,
            expectCode: 'ADDITIVE_POLICY_NOT_NULL_WITHOUT_DEFAULT',
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260004__v1.0.x__Add_Req_Col.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260004__v1.0.x__Add_Req_Col.sql',
                            content: `-- codegen-not-required: testing additive guard\nALTER TABLE dbo.[Widget] ADD [RequiredCode] NVARCHAR(50) NOT NULL;`,
                        },
                    ],
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
        {
            name: 'Warn mode records warnings without failing',
            expectPass: true,
            run: () =>
                validateMigrationCodeGenAlignment({
                    changedPaths: ['migrations/V202611260001__v1.0.x__Add_Widget.sql'],
                    files: [
                        {
                            path: 'migrations/V202611260001__v1.0.x__Add_Widget.sql',
                            content: `CREATE TABLE dbo.[Widget] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY);`,
                        },
                    ],
                    config: { mode: 'Warn' },
                    repoHasPgMigrationsDir: false,
                    repoHasGeneratedEntitiesDir: false,
                }),
        },
    ];

    let fails = 0;
    for (const tc of cases) {
        const res = tc.run();
        const codeOk = !tc.expectCode || res.findings.some((f) => f.code === tc.expectCode);
        if (res.passed === tc.expectPass && codeOk) {
            console.log(`${GREEN}self-test ok${NC}: ${tc.name}`);
        } else {
            console.log(
                `${RED}self-test FAIL${NC}: ${tc.name} (expected passed=${tc.expectPass}${tc.expectCode ? ` code=${tc.expectCode}` : ''}, got passed=${res.passed} codes=[${res.findings.map((f) => f.code).join(',')}])`,
            );
            fails += 1;
        }
    }
    if (fails > 0) {
        console.log(`\n${RED}${fails} self-test failure(s)${NC}`);
        return 1;
    }
    console.log(`\n${GREEN}all ${cases.length} self-tests passed${NC}`);
    return 0;
}

// ─── CLI & Git discovery ───────────────────────────────────────────────────────────────────────

function makeGit(root) {
    return (args, opts = {}) =>
        execFileSync('git', ['-C', root, '-c', 'core.quotePath=false', ...args], {
            encoding: 'utf8',
            maxBuffer: GIT_MAX_BUFFER,
            ...opts,
        }).trim();
}

function parseCliArgs(argv) {
    const opts = {
        selfTest: false,
        base: null,
        head: null,
        files: null,
        mode: process.env.MIGRATION_ALIGNMENT_MODE || 'Enforce',
        minBlankLines: 50,
        allowBreaking: false,
        enforcePg: true,
        enforceTs: true,
        json: false,
    };
    const positional = [];
    for (let i = 0; i < argv.length; i += 1) {
        const arg = argv[i];
        if (arg === '--self-test') opts.selfTest = true;
        else if (arg === '--base' && argv[i + 1]) opts.base = argv[++i];
        else if (arg.startsWith('--base=')) opts.base = arg.slice('--base='.length);
        else if (arg === '--head' && argv[i + 1]) opts.head = argv[++i];
        else if (arg.startsWith('--head=')) opts.head = arg.slice('--head='.length);
        else if (arg === '--files' && argv[i + 1]) {
            opts.files = [...(opts.files ?? []), ...argv[++i].split(',').map((s) => s.trim()).filter(Boolean)];
        } else if (arg.startsWith('--files=')) {
            opts.files = [...(opts.files ?? []), ...arg.slice('--files='.length).split(',').map((s) => s.trim()).filter(Boolean)];
        } else if (arg === '--mode' && argv[i + 1]) opts.mode = argv[++i];
        else if (arg.startsWith('--mode=')) opts.mode = arg.slice('--mode='.length);
        else if (arg === '--min-blank-lines' && argv[i + 1]) opts.minBlankLines = Number(argv[++i]);
        else if (arg.startsWith('--min-blank-lines=')) opts.minBlankLines = Number(arg.slice('--min-blank-lines='.length));
        else if (arg === '--allow-breaking') opts.allowBreaking = true;
        else if (arg === '--no-pg') opts.enforcePg = false;
        else if (arg === '--no-ts') opts.enforceTs = false;
        else if (arg === '--json') opts.json = true;
        else if (!arg.startsWith('-')) positional.push(arg);
    }
    if (!opts.base && positional.length >= 1) opts.base = positional[0];
    if (!opts.head && positional.length >= 2) opts.head = positional[1];
    return opts;
}

function detectRepoGeneratedEntitiesDir(root) {
    const packagesDir = join(root, 'packages');
    if (!existsSync(packagesDir)) return false;
    try {
        for (const entry of readdirSync(packagesDir, { withFileTypes: true })) {
            if (!entry.isDirectory()) continue;
            if (/Entities/i.test(entry.name) && existsSync(join(packagesDir, entry.name, 'src', 'generated'))) {
                return true;
            }
        }
    } catch {
        return false;
    }
    return false;
}

export function main(argv) {
    const opts = parseCliArgs(argv);
    if (opts.selfTest) return runSelfTests();

    let root = process.cwd();
    try {
        root = execFileSync('git', ['rev-parse', '--show-toplevel'], {
            encoding: 'utf8',
            stdio: ['ignore', 'pipe', 'pipe'],
        }).trim();
    } catch {
        root = resolve(process.cwd());
    }

    let changedPaths = [];
    if (opts.files && opts.files.length > 0) {
        changedPaths = opts.files.map(normalizePath);
    } else {
        const git = makeGit(root);
        let baseSha = opts.base;
        const headRef = opts.head;
        if (!baseSha) {
            const baseRef = process.env.BASE_REF || 'origin/next';
            try {
                baseSha = git(['merge-base', baseRef, 'HEAD'], { stdio: ['ignore', 'pipe', 'pipe'] });
            } catch (err) {
                console.error(`${RED}✗ could not resolve base ref '${baseRef}'${NC}`);
                console.error(`  ${err.stderr?.toString().trim() || err.message}`);
                console.error(`  Fetch it (e.g. \`git fetch origin next\`), pass \`--base <ref>\`, or set BASE_REF.`);
                return 1;
            }
        } else if (!headRef) {
            try {
                baseSha = git(['merge-base', baseSha, 'HEAD'], { stdio: ['ignore', 'pipe', 'pipe'] });
            } catch (err) {
                console.error(`${RED}✗ could not resolve base ref '${baseSha}'${NC}`);
                console.error(`  ${err.stderr?.toString().trim() || err.message}`);
                console.error(`  Fetch it or pass a valid ref to \`--base\`.`);
                return 1;
            }
        }

        const diffOut = git([
            'diff',
            '--name-only',
            '--diff-filter=ACMR',
            baseSha,
            ...(headRef ? [headRef] : []),
        ]);
        changedPaths = diffOut.split('\n').filter(Boolean).map(normalizePath);
        if (!headRef) {
            const untracked = git(['ls-files', '--others', '--exclude-standard', '--', 'migrations', 'migrations-pg', 'packages']);
            for (const f of untracked.split('\n')) {
                if (f) changedPaths.push(normalizePath(f));
            }
        }
    }

    // Hydrate virtual files for changed migrations, matching PG counterparts, and changed generated TS
    const filesToRead = new Set();
    for (const p of changedPaths) {
        if (TSQL_MIGRATION_PATH_RE.test(p)) {
            filesToRead.add(p);
            filesToRead.add(p.replace(/(^|\/)migrations\//i, '$1migrations-pg/').replace(/\.sql$/i, '.pg.sql'));
            filesToRead.add(p.replace(/(^|\/)migrations\//i, '$1migrations-pg/').replace(/\.sql$/i, '.pg-only'));
        } else if (PG_MIGRATION_PATH_RE.test(p) || GENERATED_TS_ENTITY_PATH_RE.test(p)) {
            filesToRead.add(p);
        }
    }

    const virtualFiles = [];
    for (const rel of filesToRead) {
        const full = join(root, rel);
        if (existsSync(full)) {
            try {
                if (statSync(full).isFile()) {
                    virtualFiles.push({ path: rel, content: readFileSync(full, 'utf8') });
                }
            } catch {
                // Skip unreadable
            }
        }
    }

    const result = validateMigrationCodeGenAlignment({
        changedPaths,
        files: virtualFiles,
        config: {
            mode: opts.mode,
            minBlankLinesBeforeCodeGen: opts.minBlankLines,
            enforceAdditiveSchemaPolicy: !opts.allowBreaking,
            enforcePgCounterpartAlignment: opts.enforcePg,
            enforceGeneratedTsAlignment: opts.enforceTs,
        },
        repoHasPgMigrationsDir: existsSync(join(root, 'migrations-pg')),
        repoHasGeneratedEntitiesDir: detectRepoGeneratedEntitiesDir(root),
    });

    if (opts.json) {
        console.log(JSON.stringify(result, null, 2));
        return result.passed ? 0 : 1;
    }

    if (!result.applicable) {
        console.log(`${DIM}${result.summary}${NC}`);
        return 0;
    }

    if (result.warnings.length > 0) {
        for (const w of result.warnings) {
            console.log(`${YELLOW}⚠ ${w}${NC}`);
        }
    }
    if (result.blockingReasons.length > 0) {
        for (const err of result.blockingReasons) {
            console.log(`${RED}✗ ${err}${NC}`);
        }
        console.log(`\n${RED}${result.summary}${NC}`);
        return 1;
    }

    console.log(`${GREEN}✓ ${result.summary}${NC}`);
    return 0;
}

function isEntryPoint() {
    if (!process.argv[1]) return false;
    try {
        return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
    } catch {
        return false;
    }
}

if (isEntryPoint()) {
    process.exit(main(process.argv.slice(2)));
}
